-- 分位点由本次全体可识别客户计算；重跑时自动更新。
USE retail_training;
WITH base AS (SELECT customer_id, DATEDIFF('2011-12-10', DATE(MAX(invoice_date))) AS recency_days, COUNT(DISTINCT invoice_no) AS frequency, SUM(amount_units) AS monetary_units FROM sales WHERE customer_id IS NOT NULL GROUP BY customer_id), scored AS (SELECT *, 5 - ((recency_days > 13.80000000) + (recency_days > 33.00000000) + (recency_days > 72.00000000) + (recency_days > 180.00000000)) AS r_score, 1 + ((frequency > 1.00000000) + (frequency > 2.00000000) + (frequency > 3.00000000) + (frequency > 6.00000000)) AS f_score, 1 + ((monetary_units > 2493440.00000000) + (monetary_units > 4874120.00000000) + (monetary_units > 9333480.00000000) + (monetary_units > 20550500.00000000)) AS m_score FROM base) SELECT *, CASE WHEN m_score>=3 THEN CASE WHEN r_score>=3 THEN IF(f_score>=3,'重要价值客户','重要发展客户') ELSE IF(f_score>=3,'重要保持客户','重要挽留客户') END ELSE CASE WHEN r_score>=3 THEN IF(f_score>=3,'一般价值客户','一般发展客户') ELSE IF(f_score>=3,'一般保持客户','一般挽留客户') END END AS segment FROM scored;